{ unsigned a;
  int n;
  scanf("%o", &a);
  scanf("%d", &n);
  a &= 0xFFFFu;                     /* 原书按 16 位字长处理 */
  if ( (n>0) )
    { printf("%o\n", moveright(a, n)); }
  else
    {  n=-n ;
      printf("%o\n", moveleft(a, n));
    }
  return 0;
}
unsigned moveright(unsigned value, int n)
{ unsigned z;
  value &= 0xFFFFu;
  z = (value >> n) | (value << (16 - n));
  return z & 0xFFFFu;
}
unsigned moveleft(unsigned value, int n)
{ unsigned z;
  value &= 0xFFFFu;
   z=(value<<n)|(value>>(16-n)) ;
  return z & 0xFFFFu;
}

